import re

def eval_expression(expr):
    # 1. トークン化: 数字（小数含む）、演算子、括弧を分割してリストにする
    tokens = re.findall(r'\d*\.\d+|\d+|[+\-*/()]', expr)
    pos = 0

    def parse_expression():
        """足し算と引き算を処理する (優先度: 低)"""
        nonlocal pos
        left = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                left += right
            else:
                left -= right
        return left

    def parse_term():
        """掛け算と割り算を処理する (優先度: 中)"""
        nonlocal pos
        left = parse_factor()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right = parse_factor()
            if op == '*':
                left *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                left /= right
        return left

    def parse_factor():
        """数値、括弧、単項マイナスを処理する (優先度: 高)"""
        nonlocal pos
        token = tokens[pos]

        # 単項マイナスの処理 (例: -5)
        if token == '-':
            pos += 1
            return -parse_factor()

        # 括弧の処理 (例: (1 + 2))
        if token == '(':
            pos += 1  # '(' をスキップ
            result = parse_expression()
            pos += 1  # ')' をスキップ
            return result

        # 数値の処理
        pos += 1
        return float(token)

    return parse_expression()

# --- テストケース ---
if __name__ == "__main__":
    test_cases = [
        ("3 + 4 * (2 - 1)", 7),
        ("-3 + 5", 2),
        ("10 / (2 + 3)", 2),
        ("2 * -3 + 10", 4),
        (" (10 + 2) * 3 ", 36),
    ]

    for expr, expected in test_cases:
        result = eval_expression(expr)
        print(f"'{expr}' -> {result} (Expected: {expected})")

    # ゼロ除算のテスト
    try:
        eval_expression("10 / 0")
    except ZeroDivisionError as e:
        print(f"Caught expected error: {e}")
